// Builds supabase/bundle/all_migrations.sql: every migration in order, then the seed, as one file
// to paste into the SQL editor of a FRESH Supabase project (D-11).
//
//   npm run bundle:sql            write the bundle
//   npm run bundle:sql -- --check exit 1 if the committed bundle is stale
//
// Each migration is wrapped so the whole bundle is safe to run twice (D-12): a marker row in
// sf_migrations.applied records every file that has run, and a file whose marker exists is skipped
// instead of failing on "already exists". The wrapped SQL is the migration text unchanged, executed
// as one string, so the first run does exactly what running the files one by one does. The marker
// table lives outside `public`, so it is never exposed through the API.
//
// The output is deterministic (no dates, stable order), so the check mode is a plain string compare.

import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const migrationsDir = path.join(root, 'supabase', 'migrations')
const outFile = path.join(root, 'supabase', 'bundle', 'all_migrations.sql')

const OPEN = '$sf_body$'
const read = (p) => readFileSync(p, 'utf8').replace(/\r\n/g, '\n').trimEnd()

function wrap(name, sql) {
  if (sql.includes(OPEN)) throw new Error(`${name} contains ${OPEN}, which the bundle uses as its quote`)
  return `-- ${'-'.repeat(75)}
-- ${name}
-- ${'-'.repeat(75)}
do $sf_migration$
begin
  if exists (select 1 from sf_migrations.applied where name = '${name}') then
    raise notice 'skipping ${name} (already applied)';
    return;
  end if;
  execute ${OPEN}
${sql}
${OPEN};
  insert into sf_migrations.applied (name) values ('${name}');
end
$sf_migration$;
`
}

export function buildBundle() {
  const files = readdirSync(migrationsDir).filter((f) => f.endsWith('.sql')).sort()
  const parts = [
    `-- SquadFinder: all migrations + seed in one file, for a FRESH Supabase project.
-- Generated by scripts/build-sql-bundle.mjs from supabase/migrations/*.sql and supabase/seed.sql.
-- Do not edit; change the sources and run \`npm run bundle:sql\`.
--
-- Safe to run more than once: files that already ran are skipped (see sf_migrations.applied).
-- Existing projects should keep applying the individual files with the Supabase CLI instead.
-- The Supabase dashboard will warn that this script is destructive; it drops and recreates
-- objects it created itself, and never touches data it did not create.

create schema if not exists sf_migrations;
create table if not exists sf_migrations.applied (
  name text primary key,
  applied_at timestamptz not null default now()
);
revoke all on schema sf_migrations from public, anon, authenticated;
revoke all on sf_migrations.applied from public, anon, authenticated;
`,
    ...files.map((f) => wrap(f, read(path.join(migrationsDir, f)))),
    wrap('seed.sql', read(path.join(root, 'supabase', 'seed.sql'))),
  ]
  return parts.join('\n') + '\n'
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const bundle = buildBundle()
  if (process.argv.includes('--check')) {
    const onDisk = existsSync(outFile) ? readFileSync(outFile, 'utf8').replace(/\r\n/g, '\n') : ''
    if (onDisk !== bundle) {
      console.error('supabase/bundle/all_migrations.sql is stale. Run: npm run bundle:sql')
      process.exit(1)
    }
    console.log('bundle is up to date')
  } else {
    mkdirSync(path.dirname(outFile), { recursive: true })
    writeFileSync(outFile, bundle, 'utf8')
    console.log(`wrote ${path.relative(root, outFile)} (${bundle.length} bytes)`)
  }
}
